    "answer": "4",
    "explain": "| **측정 위치** | • 일반적으로 작은 방을 측정하는 경우에는 약 5개소, 비교적 큰 방일 경우에는 측정소를 증가시킴<br>• 방 이외의 격벽구획이 명확하지 않은 장소(복도, 통로 등)에서는 공기의 진입, 유통, 정체 등의 상태를 고려하여 전체 환경을 대표한다고 생각되는 장소를 선택<br>• 측정하려는 방의 크기와 구조에 더 유의하여야 하나, 5개소 이하로 측정하면 올바른 평가를 얻기가 어려우며 측정 위치도 벽에서 30cm 떨어진 곳이 좋음<br>• 측정 높이는 바닥에서 측정하는 것이 원칙이지만 부득이한 경우 바닥으로부터 20~30cm 높은 위치에서 측정하기도 함 |",
